def simulate_correctly():
    stock = {
        'ATN02K12P': 2080,
        'MAR02K12P': 292,
        'MASR025K': 663
    }

    weights = {
        'ATN02K12P': 24,
        'MAR02K12P': 24,
        'MASR025K': 25
    }

    capacity = 34500

    order_book = {
        29: {'ATN02K12P': (1200, 1010), 'MAR02K12P': (0, 92), 'MASR025K': (0, 30)},
        30: {'ATN02K12P': (1000, 1387), 'MAR02K12P': (0, 227), 'MASR025K': (13, 54)},
        31: {'ATN02K12P': (800, 1600), 'MAR02K12P': (0, 371), 'MASR025K': (200, 124)},
        32: {'ATN02K12P': (1000, 312), 'MAR02K12P': (400, 209), 'MASR025K': (0, 105)},
        33: {'ATN02K12P': (1500, 531), 'MAR02K12P': (0, 72), 'MASR025K': (100, 60)},
        34: {'ATN02K12P': (1000, 0), 'MAR02K12P': (10, 0), 'MASR025K': (70, 0)},
        35: {'ATN02K12P': (500, 231), 'MAR02K12P': (0, 110), 'MASR025K': (100, 240)},
    }

    open_orders = []

    for day in range(29, 36):
        daily_capacity = capacity
        shipped_today = {'ATN02K12P': 0, 'MAR02K12P': 0, 'MASR025K': 0}

        # 1. Production arrives
        for prod, (prod_qty, order_qty) in order_book[day].items():
            stock[prod] += prod_qty

        # 2. Orders join the queue
        for prod, (prod_qty, order_qty) in order_book[day].items():
            if order_qty > 0:
                open_orders.append([day, order_qty, prod])

        # 3. Dispatch
        while open_orders and daily_capacity > 0:
            open_orders.sort(key=lambda x: (x[0], x[1], x[2]))
            idx = 0
            day_placed, remaining_qty, prod = open_orders[idx]

            available_stock = stock[prod]
            max_units_by_capacity = daily_capacity // weights[prod]
            units_to_ship = min(remaining_qty, available_stock, max_units_by_capacity)

            if units_to_ship > 0:
                shipped_today[prod] += units_to_ship
                stock[prod] -= units_to_ship
                daily_capacity -= units_to_ship * weights[prod]
                open_orders[idx][1] -= units_to_ship

            if open_orders[idx][1] == 0:
                open_orders.pop(idx)

        backordered = {'ATN02K12P': 0, 'MAR02K12P': 0, 'MASR025K': 0}
        for order in open_orders:
            backordered[order[2]] += order[1]

        # Check capacity reached
        capacity_reached = False
        if daily_capacity < capacity and open_orders:
            for order in open_orders:
                if stock[order[2]] > 0:
                    capacity_reached = True
                    break
            if not capacity_reached and daily_capacity > 0:
                open_orders.sort(key=lambda x: (x[0], x[1], x[2]))
                if stock[open_orders[0][2]] > 0 and daily_capacity < weights[open_orders[0][2]]:
                    capacity_reached = True

        print(f"Day {day}:")
        print(f"  Stock: {stock}")
        print(f"  Backordered: {backordered}")
        print(f"  Shipped: {shipped_today}")
        print(f"  Capacity reached: {capacity_reached}")
        print(f"  Open orders: {open_orders}")

